record.field:
if not records:
    raise UserError('Изберете поръчка за продажба.')
result_ids = []
for order in records:
    if order.state != 'sale':
        raise UserError('Машини се регистрират от потвърдена продажба след действителна доставка.')
    lines = env['stock.move.line'].search([
        ('move_id.sale_line_id.order_id', '=', order.id),
        ('state', '=', 'done'), ('location_dest_id.usage', '=', 'customer'),
        ('lot_id', '!=', False), ('quantity', '>', 0),
        ('product_id.product_tmpl_id.x_hm_is_machine', '=', True),
        ('company_id', '=', order.company_id.id),
    ])
    for line in lines:
        if line.product_id.tracking != 'serial':
            raise UserError('Машината %s трябва да се проследява по отделен сериен номер.' % line.product_id.display_name)
        machines = env['x_hm_machine'].search([('x_lot_id', '=', line.lot_id.id), ('x_company_id', '=', order.company_id.id)])
        if len(machines) > 1:
            raise UserError('Има повече от едно досие за сериен номер %s.' % line.lot_id.name)
        if machines:
            machine = machines
            if machine.x_sale_order_id and machine.x_sale_order_id != order:
                raise UserError('Машината %s вече има първоначална продажба. Проверете нейното досие.' % machine.x_name)
            if machine.x_partner_id.commercial_partner_id != order.partner_id.commercial_partner_id:
                raise UserError('Собственикът на досието не съвпада с клиента в продажбата.')
            if not machine.x_sale_order_id:
                machine.write({'x_sale_order_id': order.id, 'x_delivery_id': line.picking_id.id,
                    'x_delivery_date': line.picking_id.date_done.date() if line.picking_id.date_done else False})
        else:
            machine = env['x_hm_machine'].with_company(order.company_id).with_context(mail_create_nosubscribe=True).create({
                'x_name': '%s / %s' % (line.product_id.display_name, line.lot_id.name),
                'x_lot_id': line.lot_id.id, 'x_company_id': order.company_id.id,
                'x_partner_id': order.partner_id.commercial_partner_id.id,
                'x_sale_order_id': order.id, 'x_delivery_id': line.picking_id.id,
                'x_delivery_date': line.picking_id.date_done.date() if line.picking_id.date_done else False,
            })
        if machine.id not in result_ids:
            result_ids.append(machine.id)
if not result_ids:
    raise UserError('Няма доставени машини със сериен номер. Отбележете „Машина със сервизно досие“ в артикула и проверете завършената доставка.')
action = {'type': 'ir.actions.act_window', 'name': 'Досиета на машините', 'res_model': 'x_hm_machine', 'view_mode': 'list,form', 'domain': [('id', 'in', result_ids)]}
if len(result_ids) == 1:
    action.update({'view_mode': 'form', 'res_id': result_ids[0]})

record.ensure_one()
if record.x_retired:
    raise UserError('Машината е изведена от обслужване.')
action = {'type': 'ir.actions.act_window', 'name': 'Нова сервизна заявка', 'res_model': 'x_hm_job', 'view_mode': 'form', 'target': 'current', 'context': {'default_x_machine_id': record.id, 'default_x_technician_id': env.uid}}

ids = []
for plan in records:
    if not plan.x_enabled or plan.x_machine_id.x_retired:
        raise UserError('Планът трябва да е активен и машината да е в обслужване.')
    job = env['x_hm_job'].search([('x_plan_id', '=', plan.id), ('x_state', 'not in', ['done', 'cancel'])], limit=1)
    if not job:
        job = env['x_hm_job'].with_company(plan.x_company_id).with_context(mail_create_nosubscribe=True).create({
            'x_name': plan.x_name, 'x_machine_id': plan.x_machine_id.id,
            'x_plan_id': plan.id, 'x_technician_id': plan.x_technician_id.id,
            'x_due_date': plan.x_next_date, 'x_problem': plan.x_instructions or plan.x_name,
            'x_state': 'new', 'x_kind': 'onsite', 'x_coverage': 'review',
        })
    ids.append(job.id)
action = {'type': 'ir.actions.act_window', 'name': 'Заявки по планове', 'res_model': 'x_hm_job', 'view_mode': 'list,form', 'domain': [('id', 'in', ids)]}
if len(ids) == 1:
    action.update({'view_mode': 'form', 'res_id': ids[0]})

plans = env['x_hm_plan'].search([('x_enabled', '=', True), ('x_machine_id.x_retired', '=', False)])
due = plans.filtered(lambda p: p.x_due)
if due:
    action = env.ref('hydromotor_service.action_plan_job').with_context(active_model='x_hm_plan', active_ids=due.ids, active_id=due[0].id).run()
else:
    action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': 'Сервизни планове', 'message': 'Няма настъпили обслужвания по въведените дати и моточасове.', 'type': 'success', 'sticky': False}}

for job in records:
    if job.x_state not in ['new', 'planned']:
        raise UserError('Може да се планира нова или вече планирана заявка.')
    if not job.x_planned_start or not job.x_technician_id:
        raise UserError('Посочете начало на посещението и отговорен техник.')
    job.write({'x_state': 'planned'})

for job in records:
    if job.x_state not in ['new', 'planned', 'progress']:
        raise UserError('Завършена или отказана заявка не може да се започне отново.')
    if not job.x_technician_id:
        raise UserError('Посочете отговорен техник.')
    job.write({'x_state': 'progress'})

for job in records:
    if job.x_state == 'done':
        raise UserError('Завършена заявка не може да се отказва.')
    job.write({'x_state': 'cancel'})

for job in records:
    if job.x_state == 'done':
        continue
    if job.x_state == 'cancel':
        raise UserError('Отказана заявка не може да бъде завършена.')
    if not job.x_work_done or not job.x_work_done.strip():
        raise UserError('Опишете извършените дейности.')
    if not job.x_technician_id or job.x_coverage == 'review':
        raise UserError('Посочете техник и решение за начина на заплащане.')
    plan = job.x_plan_id
    if plan and plan.x_interval_hours > 0 and not job.x_has_meter:
        raise UserError('Планът е по моточасове. Въведете текущото отчитане.')
    if job.x_has_meter and job.x_meter_hours < job.x_machine_id.x_hours:
        raise UserError('Моточасовете не могат да са по-малко от последния отчет в досието.')
    now = datetime.datetime.now()
    if job.x_has_meter:
        previous = env['x_hm_meter'].search([('x_job_id', '=', job.id)], limit=1)
        if not previous:
            env['x_hm_meter'].with_context(mail_create_nosubscribe=True).create({
                'x_name': job.x_reference or job.x_name, 'x_machine_id': job.x_machine_id.id,
                'x_job_id': job.id, 'x_date': now.date(), 'x_hours': job.x_meter_hours,
                'x_note': 'Отчет при завършване на сервизната заявка.',
            })
    if plan:
        plan.write({
            'x_next_date': now.date() + datetime.timedelta(days=plan.x_interval_days) if plan.x_interval_days > 0 else False,
            'x_next_hours': job.x_meter_hours + plan.x_interval_hours if plan.x_interval_hours > 0 else 0,
        })
    job.write({'x_state': 'done', 'x_closed_at': now})

record.ensure_one()
job = record
if job.x_state == 'cancel':
    raise UserError('Отказана заявка не може да създаде оферта.')
order = job.x_sale_order_id
repair = job.x_repair_id
if order and order.state == 'cancel':
    raise UserError('Свързаната оферта е отказана. Отворете я от полето „Сервизна оферта / поръчка“ и проверете следващото действие.')
if not order:
    if repair:
        if not repair.sale_order_id:
            repair.action_create_sale_order()
        order = repair.sale_order_id
    else:
        order = env['sale.order'].with_company(job.x_company_id).with_context(mail_create_nosubscribe=True).create({
            'partner_id': job.x_partner_id.id, 'company_id': job.x_company_id.id,
            'origin': '%s / %s' % (job.x_reference or job.x_name, job.x_machine_id.x_name),
        })
    if order.state == 'cancel':
        raise UserError('Офертата на свързания ремонт е отказана. Проверете ремонта и неговата оферта.')
    job.write({'x_sale_order_id': order.id})
action = {'type': 'ir.actions.act_window', 'res_model': 'sale.order', 'view_mode': 'form', 'res_id': order.id, 'target': 'current'}

for r in records:
    identity = '%s/%s' % (r.x_company_id.id, r.x_lot_id.id)
    if r.x_identity_key and r.x_identity_key != identity:
        raise UserError('Фирмата и серийният номер на записано досие не могат да се сменят. Създайте отделно досие за друга машина.')
    if not r.x_identity_key:
        r.write({'x_identity_key': identity})
    if r.x_lot_id.product_id.tracking != 'serial':
        raise UserError('За машината е необходимо проследяване по сериен номер, а не по партида.')
    if r.x_lot_id.company_id and r.x_lot_id.company_id != r.x_company_id:
        raise UserError('Серийният номер е от друга фирма.')
    if env['x_hm_machine'].search_count([('id', '!=', r.id), ('x_lot_id', '=', r.x_lot_id.id), ('x_company_id', '=', r.x_company_id.id)]):
        raise UserError('За този сериен номер вече има досие в същата фирма.')
    if r.x_warranty_hours < 0:
        raise UserError('Гаранционният лимит не може да е отрицателен.')
    if r.x_warranty_start and r.x_warranty_end and r.x_warranty_end < r.x_warranty_start:
        raise UserError('Краят на гаранцията е преди началото.')
    if r.x_sale_order_id and r.x_sale_order_id.company_id != r.x_company_id:
        raise UserError('Първоначалната продажба е от друга фирма.')
    if r.x_delivery_id and r.x_delivery_id.company_id != r.x_company_id:
        raise UserError('Доставката е от друга фирма.')

for r in records:
    vals = {}
    if r.x_machine_lock_id and r.x_machine_lock_id != r.x_machine_id:
        raise UserError('Записаната заявка е за друга машина. Създайте нова заявка за правилната машина.')
    if not r.x_machine_lock_id:
        vals['x_machine_lock_id'] = r.x_machine_id.id
    if not r.x_reference:
        vals['x_reference'] = 'SRV-%06d' % r.id
    if not r.x_partner_id:
        vals['x_partner_id'] = r.x_machine_id.x_partner_id.id
    if vals:
        r.write(vals)
    if r.x_state == 'done' and not r.x_closed_at:
        raise UserError('Завършвайте заявката с бутона „Завърши“, за да се запишат отчетът и следващият срок.')
    if r.x_state == 'planned' and (not r.x_planned_start or not r.x_technician_id):
        raise UserError('Планираната заявка изисква начална дата и отговорен техник.')
    if r.x_state == 'progress' and not r.x_technician_id:
        raise UserError('За работа по заявката трябва да има отговорен техник.')
    if r.x_labor_hours < 0 or r.x_travel_km < 0 or r.x_meter_hours < 0:
        raise UserError('Часовете и пробегът не могат да са отрицателни.')
    if r.x_planned_end and (not r.x_planned_start or r.x_planned_end < r.x_planned_start):
        raise UserError('Краят на посещението трябва да е след началото.')
    if r.x_plan_id and r.x_plan_id.x_machine_id != r.x_machine_id:
        raise UserError('Планът е за друга машина.')
    if r.x_sale_order_id:
        if r.x_sale_order_id.company_id != r.x_company_id or r.x_sale_order_id.partner_id.commercial_partner_id != r.x_partner_id.commercial_partner_id:
            raise UserError('Сервизната оферта трябва да е за същата фирма и клиент.')
        if r.x_sale_order_id == r.x_machine_id.x_sale_order_id:
            raise UserError('Сервизът изисква собствена поръчка, отделна от първоначалната продажба на машината.')
    if r.x_repair_id:
        repair = r.x_repair_id
        if repair.lot_id != r.x_machine_id.x_lot_id or repair.company_id != r.x_company_id:
            raise UserError('Ремонтът трябва да е за същия сериен номер и фирма.')
        if repair.partner_id.commercial_partner_id != r.x_partner_id.commercial_partner_id:
            raise UserError('Клиентът в ремонта трябва да съвпада със заявката.')
        if r.x_sale_order_id and repair.sale_order_id != r.x_sale_order_id:
            raise UserError('За свързан ремонт използвайте неговата собствена оферта. Не свързвайте две различни поръчки за едно обслужване.')
        if env['x_hm_job'].search_count([('id', '!=', r.id), ('x_repair_id', '=', repair.id)]):
            raise UserError('Този ремонт вече е свързан с друга сервизна заявка.')

for r in records:
    if r.x_interval_days < 0 or r.x_interval_hours < 0 or r.x_next_hours < 0:
        raise UserError('Интервалите и моточасовете не могат да бъдат отрицателни.')
    if r.x_enabled:
        if r.x_interval_days <= 0 and r.x_interval_hours <= 0:
            raise UserError('Задайте интервал в дни, моточасове или и двете.')
        if r.x_interval_days > 0 and not r.x_next_date:
            raise UserError('За план по дни задайте дата за следващо обслужване.')
        if r.x_interval_hours > 0 and r.x_next_hours <= 0:
            raise UserError('Задайте абсолютния праг за следващо обслужване по моточасове.')
        if r.x_interval_days == 0 and r.x_next_date:
            raise UserError('Дата за следващо обслужване изисква положителен интервал в дни.')
        if r.x_interval_hours == 0 and r.x_next_hours > 0:
            raise UserError('Праг по моточасове изисква положителен интервал в моточасове.')

for r in records:
    if r.x_hours < 0 or r.x_date > datetime.date.today():
        raise UserError('Отчетът не може да е отрицателен или с бъдеща дата.')
    earlier = env['x_hm_meter'].search([('id', '!=', r.id), ('x_machine_id', '=', r.x_machine_id.id), ('x_date', '<=', r.x_date)])
    later = env['x_hm_meter'].search([('id', '!=', r.id), ('x_machine_id', '=', r.x_machine_id.id), ('x_date', '>', r.x_date)])
    if earlier and r.x_hours < max(earlier.mapped('x_hours')):
        raise UserError('Отчетът е по-малък от вече въведен отчет за същата или по-ранна дата.')
    if later and r.x_hours > min(later.mapped('x_hours')):
        raise UserError('Историческият отчет надвишава по-късно отчитане.')
    if r.x_job_id and r.x_job_id.x_machine_id != r.x_machine_id:
        raise UserError('Заявката е за друга машина.')
